 "content": "from collections import Counter


def transform(grid):
    """Restore masked cells in the framed periodic-color grid."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Infer the diagonal cycle from the intact interior. The motif repeats with
    # r+c modulo its period; modal values make the fit robust to the small
    # exceptional motif near the upper-left corner.
    interior = [(r, c, grid[r][c])
                for r in range(3, h) for c in range(3, w)
                if grid[r][c] != 0]
    best = None
    for period in range(2, 13):
        counts = [Counter() for _ in range(period)]
        for r, c, value in interior:
            counts[(r + c) % period][value] += 1
        mapping = [count.most_common(1)[0][0] if count else 0 for count in counts]
        score = sum(counts[i][mapping[i]] for i in range(period))
        candidate = (score, -period, mapping)
        if best is None or candidate[:2] > best[:2]:
            best = candidate
    mapping = best[2]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                period = len(mapping)
                out[r][c] = mapping[(r + c) % period]
    return out
